public static IEnumerator RunCore(Action<string> log){
var cycle=UnityEngine.Object.FindFirstObjectByType<DayNightCycle>();cycle.enabled=false;cycle.isShopOpen=true;cycle.currentTime=10;
var manager=UnityEngine.Object.FindFirstObjectByType<OrderManager>();manager.enabled=false;var policy=manager.GetComponent<DistrictDeliveryPolicy>();var registered=(List<DeliveryPoint>)Get(manager,"deliveryPoints");
