var random=UnityEngine.Random.state;UnityEngine.Random.InitState(748);int[] tally=new int[3];for(int i=0;i<10000;i++){var p=policy.Choose(registered);tally[policy.oldCity.Contains(p)?0:policy.eastCity.Contains(p)?1:2]++;}UnityEngine.Random.state=random;Check(Math.Abs(tally[0]-1500)<200&&Math.Abs(tally[1]-5000)<250&&Math.Abs(tally[2]-3500)<250,"1만 회 지역 선택 비중: "+string.Join("/",tally),log);
var player=UnityEngine.Object.FindFirstObjectByType<PlayerCombat>();player.GetComponent<PlayerMove>().enabled=false;player.GetComponent<CharacterController>().enabled=false;var inv=player.GetComponent<ToppingInventory>();inv.RemoveItem();inv.RemovePizza();inv.ClearPackagedPizzas();Cursor.lockState=CursorLockMode.Locked;
var robbery=UnityEngine.Object.FindFirstObjectByType<RobberyManager>();robbery.enabled=false;
var nav=UnityEngine.Object.FindFirstObjectByType<NavigationManager>();var old=nav.NavigationTarget;var origin=new GameObject("District gameplay origin");nav.SetNavigationTarget(origin.transform);var shop=UnityEngine.Object.FindObjectsByType<DeliveryService.Mok.Navigation.NavigationPlace>(FindObjectsSortMode.None).First(p=>p.kind==DeliveryService.Mok.Navigation.NavigationPlaceKind.Pizza);int routes=0;Physics.SyncTransforms();
foreach(var p in registered){Set(manager,"currentTargetDeliveryID",p.DeliveryPointID);origin.transform.position=shop.Destination.position;nav.ResumeDelivery();Check(nav.DisplayPath.Count>0,"매장 → "+p.DeliveryPointID,log);origin.transform.position=p.transform.position;nav.SelectPlace(shop);Check(nav.DisplayPath.Count>0,p.DeliveryPointID+" → 매장",log);if(!policy.oldCity.Contains(p)){bool reachable=false;foreach(var dir in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right})if(Physics.Raycast(p.transform.position+Vector3.up*.85f+dir*2,-dir,out var hit,3,~0,QueryTriggerInteraction.Ignore)&&hit.collider.GetComponentInParent<DeliveryPoint>()==p)reachable=true;Check(reachable,"배달함 접근: "+p.DeliveryPointID,log);}routes++;}
nav.SetNavigationTarget(old);nav.StopGuidance();UnityEngine.Object.Destroy(origin);
// 실제 수락 경로와 배달함 상호작용으로 두 신규 지역의 주문을 완료한다.
foreach(var target in new[]{policy.eastCity[0],policy.westQuarter[0]}){
var pending=(List<PizzaOrder>)Get(manager,"pendingOrders");pending.Clear();Set(manager,"activeOrder",null);var order=new PizzaOrder{orderName="테스트",toppings=new List<string>()};pending.Add(order);Check(manager.TryAcceptOrder(order),"실제 주문 수락",log);Check(registered.Contains(manager.CurrentTargetDeliveryPoint),"수락 시 지역 정책으로 유효 배달지 선택",log);Set(manager,"currentTargetDeliveryID",target.DeliveryPointID);
var p=target.transform.position;bool hitTarget=false;foreach(var direction in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right})if(Physics.Raycast(p+Vector3.up*.85f+direction*2,-direction,out var hit,3,~0,QueryTriggerInteraction.Ignore)&&hit.collider.GetComponentInParent<DeliveryPoint>()==target)hitTarget=true;Check(hitTarget,"배달함 조준 가능: "+target.DeliveryPointID,log);
var pizza=new PizzaData(new List<string>{"dough","sauce","cheese"},true);inv.AddPackagedDataStack(new List<PizzaData>{pizza});int money=MoneyManager.Instance.currentMoney;target.Interact(inv);Check(!manager.HasActiveOrder&&!inv.HasPackagedPizzas()&&MoneyManager.Instance.currentMoney>money,"배달 완료·피자 소모·정산: "+target.DeliveryPointID,log);}
NavMesh.SamplePosition(new Vector3(-265,0,-5),out var ground,3,NavMesh.AllAreas);player.transform.position=ground.position;Physics.SyncTransforms();Check(robbery.InHighRiskDistrict&&robbery.CheckInterval==12&&robbery.SpawnChance==85,"빈민촌 12초/85%",log);Check(robbery.CanSpawnNow,"피자 없이 현금을 가진 플레이어도 대상",log);
Set(robbery,"districtWaveMin",3);Set(robbery,"districtWaveMax",3);Check(robbery.TrySpawnForTesting(),"빈민촌 강도 무리 소환",log);yield return null;var bandits=UnityEngine.Object.FindObjectsByType<RobberAI>(FindObjectsSortMode.None);Check(bandits.Length==3,"동시에 강도 3명",log);Check(!robbery.TrySpawnForTesting()&&UnityEngine.Object.FindObjectsByType<RobberAI>(FindObjectsSortMode.None).Length==3,"동시 인원 상한",log);foreach(var b in bandits)b.enabled=false;
// 피자가 있으면 현금보다 피자를 먼저 가져가고 중복 강탈하지 않는다.
var one=new PizzaData(new List<string>{"dough","sauce","cheese"},true);inv.AddPackagedDataStack(new List<PizzaData>{one});int before=MoneyManager.Instance.currentMoney;Call(bandits[0],"TakePackage");Check(bandits[0].StolenCount==1&&!inv.HasPackagedPizzas()&&MoneyManager.Instance.currentMoney==before,"피자 우선 강탈",log);
Call(bandits[1],"TakePackage");int cash=bandits[1].StolenCash;Check(cash>=before*.1f-1&&cash<=before*.2f+1&&MoneyManager.Instance.currentMoney==before-cash,"피자 없으면 현금 10~20% 강탈: "+cash,log);Check(bandits[1].GetComponent<RobberTheftFeedback>().MarkerVisible&&bandits[1].GetComponent<RobberTheftFeedback>().WarningVisible,"현금 도난 경고·추적 표시",log);
Call(bandits[2],"TakePackage");Check(bandits[2].StolenCash==0&&MoneyManager.Instance.currentMoney==before-cash,"동시 현금 강탈 보호",log);
Check(bandits[1].ReceiveKick(Vector3.right),"발차기로 현금 강도 제압",log);var cashLoot=UnityEngine.Object.FindObjectsByType<RobberLoot>(FindObjectsSortMode.None).First(l=>l.Cash>0);cashLoot.Interact(inv);cashLoot.Interact(inv);Check(MoneyManager.Instance.currentMoney==before&&bandits[1].StolenCash==0,"훔친 돈 회수·중복 지급 차단",log);
bandits[0].ReceiveKick(Vector3.right);var pizzaLoot=UnityEngine.Object.FindObjectsByType<RobberLoot>(FindObjectsSortMode.None).First(l=>l.Count>0);pizzaLoot.Interact(inv);Check(inv.GetHeldPackagedPizzas().Count==1,"피자 원본 회수",log);inv.ClearPackagedPizzas();
foreach(var b in bandits)UnityEngine.Object.Destroy(b.gameObject);yield return null;
player.transform.position=new Vector3(-176,0,-5);Check(!robbery.InHighRiskDistrict&&robbery.ActiveLimit==1&&robbery.CheckInterval==60&&robbery.SpawnChance==15,"입구 주차장·일반 도시 기존 위험도 복귀",log);
MoneyManager.Instance.currentMoney=0;Check(!RobberyMoney.CanTake&&!robbery.CanSpawnNow,"무일푼·피자 없음이면 강탈 대상 제외",log);
// 실제 자동 출몰 경로에서도 화면 밖에서 여러 명이 나온다.
MoneyManager.Instance.currentMoney=10000;typeof(RobberyMoney).GetField("protectedUntil",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,0f);player.transform.position=ground.position;Set(robbery,"districtProtectedUntil",0f);Set(robbery,"currentDay",cycle.currentDay);Set(robbery,"encounterProgress",1f);Set(robbery,"districtChance",100f);Call(robbery,"Update");yield return null;var natural=UnityEngine.Object.FindObjectsByType<RobberAI>(FindObjectsSortMode.None);Check(natural.Length>=2&&natural.Length<=3&&natural.All(r=>!r.IsTestSpawn),"자동 출몰로 2~3명 생성",log);
foreach(var b in natural)b.enabled=false;var near=natural[0];near.GetComponent<NavMeshAgent>().Warp(ground.position+Vector3.forward);Physics.SyncTransforms();Check(near.CanReachVictim(),"피자 없는 도보 플레이어에게 접근 가능",log);Call(near,"Update");Check(near.State==RobberAI.Phase.Windup,"현금 강탈 준비 동작",log);Set(near,"stateStarted",Time.time-2f);Call(near,"Update");Check(near.StolenCash>0&&near.State==RobberAI.Phase.Escape,"접근·준비·현금 강탈·도주 실제 상태 전환",log);foreach(var b in natural)UnityEngine.Object.Destroy(b.gameObject);yield return null;
// 도주 제한이 끝나면 현금도 회수 불가 상태로 퇴장한다.
MoneyManager.Instance.currentMoney=10000;typeof(RobberyMoney).GetField("protectedUntil",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,0f);player.transform.position=ground.position;Set(robbery,"districtProtectedUntil",0f);Check(robbery.TrySpawnForTesting(),"도주 시간 검사 소환",log);yield return null;var escaped=UnityEngine.Object.FindObjectsByType<RobberAI>(FindObjectsSortMode.None).First();escaped.enabled=false;Call(escaped,"TakeCash");Set(escaped,"stolenElapsed",45f);Call(escaped,"Update");yield return null;Check(escaped==null,"현금 강도도 회수 제한 후 퇴장",log);
foreach(var r in UnityEngine.Object.FindObjectsByType<RobberAI>(FindObjectsSortMode.None))UnityEngine.Object.Destroy(r.gameObject);yield return null;
var storage=UnityEngine.Object.FindFirstObjectByType<BikePizzaStorage>();var bike=storage.bikeController;Set(storage,"storedPizzas",new List<PizzaData>());storage.GetComponent<BikeCargoVisual>().Refresh();
NavMesh.SamplePosition(new Vector3(7.5f,0,47.5f),out var road,20,NavMesh.AllAreas);var start=road.position+Vector3.up*.5f;bike.transform.position=start;var offset=(Vector3)Get(bike,"localOffset");bike.sphereRB.position=start-bike.transform.rotation*offset;bike.sphereRB.transform.position=bike.sphereRB.position;bike.sphereRB.constraints=RigidbodyConstraints.FreezeAll;Physics.SyncTransforms();
Check(bike.EnterBike(player.gameObject),"현금 강탈 검사 오토바이 탑승",log);typeof(RobberyMoney).GetField("protectedUntil",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,0f);Check(robbery.TrySpawnForTesting(),"빈 배달통 탑승자 대상 소환",log);yield return null;var bikeRobber=UnityEngine.Object.FindFirstObjectByType<RobberAI>();bikeRobber.enabled=false;var wanted=storage.transform.position-bike.transform.forward*1.2f;wanted.y=road.position.y;NavMesh.SamplePosition(wanted,out var rear,3,NavMesh.AllAreas);bikeRobber.GetComponent<NavMeshAgent>().Warp(rear.position);Physics.SyncTransforms();Check(bikeRobber.CanReachCargo(storage),"빈 배달통에서도 후방 접근 판정",log);int wallet=MoneyManager.Instance.currentMoney;Call(bikeRobber,"Update");Check(bikeRobber.StolenCash>0&&storage.StoredCount==0&&MoneyManager.Instance.currentMoney==wallet-bikeRobber.StolenCash,"오토바이 탑승 중 피자 없으면 현금 강탈",log);bike.ExitBike();
